mapper.select:
select ppa.plm_attachment_id, ppa.plm_id, ppa.plm_attachment_category, ppa.document_name, ppa.description, ppa.make_up, ppa.plm_type, ppa.change_iq, ppa.change_time, ppa.five_classification_id, (select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id and faam.table_name = 'PLM_ATTACHMENT' and faam.table_pk_value = ppa.plm_attachment_id) file_name
from plm_attachment ppa where ppa.plm_attachment_category = 'PLM_FC_ATTACHMENT'
AND ppa.five_classification_id = #{fiveClassificationId}

SELECT t1.document_name, t1.file_id, sf.file_name, sf.file_type, sf.upload_date, sf.file_size, t1.plm_attachment_id, t1.plm_attachment_category as source_type, t1.plm_id, t1.description, t1.make_up, (SELECT su.description FROM sys_user su WHERE su.user_id = sf.last_updated_by) uploadPerson FROM ( SELECT pa.document_name,pa.plm_attachment_id,pa.plm_id,pa.plm_attachment_category, pa.source_id AS file_id,pa.description,pa.make_up, (SELECT a.attachment_id FROM sys_attachment a WHERE a.SOURCE_KEY =CONCAT((CONCAT(pa.plm_type,'-')),pa.plm_id) AND a.source_type = #{plmAttachmentCategory}) attachment_id FROM plm_attachment pa
pa.plm_id = #{plmId} AND pa.plm_type = #{plmType} AND pa.plm_attachment_category = #{plmAttachmentCategory}
AND pa.change_iq = #{changeIq}
) t1 LEFT JOIN sys_file sf ON sf.file_id = t1.file_id

select pa.*,
(SELECT wm_concat(aa.file_name)
FROM fnd_atm_attachment aa, fnd_atm_attachment_multi am
WHERE aa.attachment_id = am.attachment_id
AND am.table_name = 'PLM_ATTACHMENT'
AND am.table_pk_value = pa.plm_attachment_id
) AS file_name
from plm_attachment pa

    1=1

        AND pa.change_iq = #{changeIq}


        AND pa.plm_id = #{plmId}


        AND pa.plm_attachment_category = #{plmAttachmentCategory}

select pa.* from plm_attachment pa


        AND pa.change_iq = #{changeIq}


        AND pa.plm_id = #{plmId}


        AND pa.plm_type = #{plmType}

select pa.* from plm_attachment pa

    1=1
    AND pa.change_delete !='DELETE'

        AND pa.change_iq = #{changeIq}


        AND pa.plm_id = #{plmId}


        AND pa.plm_type = #{plmType}

        SELECT
	MAX(pa.change_time) AS chang_time
FROM
	plm_attachment pa
WHERE
	pa.plm_id = #{plmId}
AND pa.plm_type = #{plmType}
GROUP BY
	pa.plm_id;

select * from( select hba.plm_attachment_id as plm_attachment_id, hba.document_name as document_name, sa.attachment_id attachment_id, sf.file_id as file_id, sf.file_name as file_name, sf.file_size as file_size, (select su.description from sys_user su where sf.last_updated_by = su.user_id) as upload_person, sf.last_update_date as uploadDate from plm_attachment hba, sys_attachment sa, sys_file sf where hba.plm_attachment_id = sa.source_key and hba.plm_source_type = sa.source_type and sa.attachment_id = sf.attachment_id
and hba.plm_attachment_id = #{plmAttachmentId}
and hba.plm_id = #{plmId}
) qf order by qf.uploadDate desc

