update plm_attachment pa set pa.change_iq=#{changeIq}
 where pa.plm_id = #{plmId}
 AND pa.plm_type = #{plmType}
 AND pa.change_iq = #{changeIqOld}

mapper.delete:
DELETE  FROM  SYS_FILE  f

    f.ATTACHMENT_ID in
    (
         select  sa.ATTACHMENT_ID  from
         SYS_ATTACHMENT  SA
         inner join PLM_ATTACHMENT PA on SA.SOURCE_KEY = pa.PLM_ATTACHMENT_ID
         and SA.SOURCE_TYPE=PA.PLM_ATTACHMENT_CATEGORY
         where PA.PLM_ID= #{plmId,jdbcType=BIGINT}
         and PA.PLM_TYPE=#{plmAttachmentCategory,jdbcType=VARCHAR}
    )

DELETE from SYS_ATTACHMENT SA

    SA.SOURCE_KEY=#{plmId}
    and
    SA.SOURCE_TYPE=#{plmAttachmentCategory,jdbcType=VARCHAR}
